(() => {
'use strict';
const API='https://certus-api.onrender.com', $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tokenKey='certus_token', userKey='certus_user';
let token=sessionStorage.getItem(tokenKey)||'', user=(()=>{try{return JSON.parse(sessionStorage.getItem(userKey)||'null')}catch{return null}})(), view='dashboard', cache={}, employeeQuery='', recordQuery='', recordTypeFilter='Todos', requestQuery='', requestStatusFilter='Todos';
const root=$('#app'), views={dashboard:'Visão geral',employees:'Funcionários',branches:'Filiais',schedules:'Jornadas',records:'Registros de ponto',requests:'Ajustes',users:'Acessos de funcionários',reports:'Relatórios e exportações',terminals:'Terminais e dispositivos',settings:'Configurações e privacidade',password:'Minha senha',worker:'Meu ponto',unavailable:'Recursos indisponíveis'};
async function api(path,opts={}){const headers={'Accept':'application/json',...(opts.body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{}) ,...(opts.headers||{})};const r=await fetch(API+path,{...opts,headers});let data={};try{data=await r.json()}catch{}if(r.status===401){logout('Sessão encerrada por segurança. Entre novamente.');throw Error('Sessão expirada')}if(!r.ok)throw Error(data.error||`Falha na API (${r.status})`);return data}
function message(txt,bad=false){const n=$('#message');if(n){n.textContent=txt;n.className='message'+(bad?' bad':'');n.hidden=!txt}}
function login(note=''){token='';user=null;sessionStorage.removeItem(tokenKey);sessionStorage.removeItem(userKey);root.innerHTML=`<main class="login"><form id="login-form" class="card login-card"><div class="brand"><img class="brand-logo" src="./certus-logo-color.png" alt="Certus by VagasIO"></div><h1>Entrar na sua empresa</h1><p>Use sua conta individual do Certus.</p><div id="message" class="message" ${note?'':'hidden'}>${esc(note)}</div><label>Identificador da empresa<input name="slug" autocomplete="organization" required value="vagasio"></label><label>E-mail<input name="email" type="email" autocomplete="username" required></label><label>Senha<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Entrar</button><p class="muted">Sua senha é enviada somente à API segura do Certus. A sessão fica neste navegador e termina ao fechar a aba.</p><div class="login-links"><button class="text-button" type="button" id="forgot-password">Esqueci minha senha</button></div><div id="recovery-info" class="recovery-box" hidden></div></form></main>`;
$('#forgot-password').onclick=()=>{const n=$('#recovery-info');n.hidden=!n.hidden;if(!n.hidden&&!$('#recovery-email'))n.innerHTML=`<div class="recovery-form"><label>E-mail cadastrado<input id="recovery-email" type="email" autocomplete="email" required></label><button id="recovery-submit" class="secondary" type="button">Consultar recuperação</button></div><div id="recovery-result" class="message" hidden></div>`;$('#recovery-submit')?.addEventListener('click',startRecovery)};$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Verificando…';try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({company_slug:f.get('slug'),email:f.get('email'),password:f.get('password')})});token=d.access_token;user=d.user;sessionStorage.setItem(tokenKey,token);sessionStorage.setItem(userKey,JSON.stringify(user));await shell()}catch(err){message(err.message,true);b.disabled=false;b.textContent='Entrar'}}}
function logout(note=''){token='';user=null;sessionStorage.removeItem(tokenKey);sessionStorage.removeItem(userKey);login(note)}
function showInitialAccess(email,password){const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<form class="card dialog-card" method="dialog"><h2>Senha inicial redefinida</h2><p>Copie agora e entregue pelo canal seguro ao titular da conta. Ela aparece uma vez.</p><label>E-mail<input readonly value="${esc(email)}"></label><label>Senha temporária<input readonly id="recovery-temp-password" value="${esc(password)}"></label><div class="actions"><button class="secondary" id="copy-recovery-password" type="button">Copiar senha</button><button class="primary" value="done">Concluir</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('#copy-recovery-password').onclick=async()=>{try{await navigator.clipboard.writeText(password);d.querySelector('#copy-recovery-password').textContent='Copiada'}catch{d.querySelector('#recovery-temp-password').select()}};d.addEventListener('close',()=>{d.remove();login('Senha inicial redefinida. Entre com a nova senha.')})}
function shell(){if(user.role==='employee'&&view==='dashboard')view='worker';if(user.role!=='employee'&&view==='worker')view='dashboard';root.innerHTML=`<div class="layout"><aside class="side"><div class="brand"><img class="brand-logo" src="./certus-logo-color.png" alt="Certus by VagasIO"></div><div class="org"><small>EMPRESA AUTENTICADA</small><b id="org"></b></div><nav>${Object.entries(views).filter(([k])=>user.role==='employee'?['worker','password'].includes(k):k!=='worker'&&(k!=='users'||['company_admin','hr'].includes(user.role))&&(k!=='terminals'||['company_admin','hr'].includes(user.role))).map(([k,v])=>`<button data-view="${k}">${v}</button>`).join('')}</nav><div class="side-bottom"><p class="side-help"><strong>Ajuda e privacidade</strong><span>Dados da empresa isolados por sessão.</span></p><button id="logout" class="logout">Sair da conta</button></div></aside><main class="main"><header><div><small id="crumb"></small><h1 id="title"></h1></div><div id="identity"></div></header><div class="warning"><b>Ambiente da organização.</b> Os dados exibidos são os retornados pela API para sua empresa e seu perfil. A hora das marcações é definida pelo servidor.</div><div id="message" class="message" hidden></div><section id="content"></section><footer><div class="footer-brand"><img src="./certus-logo-white.png" alt="Certus by VagasIO"></div><span>Certus · dados e recursos vinculados à sua sessão autenticada</span></footer></main></div>`;$('#org').textContent=user.company.name;const roleNames={company_admin:'Administrador titular',manager:'Gerente',hr:'RH',supervisor:'Supervisor',employee:'Funcionário'};$('#identity').textContent=`${user.name} · ${roleNames[user.role]||'Usuário'}`;$('#logout').onclick=()=>logout('Você saiu da conta.');$$('[data-view]').forEach(b=>b.onclick=()=>load(b.dataset.view));load(view)}
const $$=s=>[...document.querySelectorAll(s)];
async function load(v){view=v;$$('[data-view]').forEach(b=>{const active=b.dataset.view===v;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#title').textContent=views[v];$('#title').tabIndex=-1;$('#crumb').textContent=user.company.name;message('');$('#content').innerHTML='<div class="card">Carregando…</div>';try{$('#content').innerHTML=await render(v);bind()}catch(e){$('#content').innerHTML=`<div class="card error">${esc(e.message)}</div>`}}
const formatDateTime=v=>{if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(d)};
const eventLabel=v=>({entry:'Entrada',break_start:'Saída para intervalo',break_end:'Retorno do intervalo',exit:'Saída'})[v]||String(v||'—');const statusLabel=v=>({active:'Ativo',inactive:'Inativo',leave:'Afastado',pending:'Pendente',approved:'Aprovado',rejected:'Rejeitado',needs_info:'Precisa de informação',validated:'Validado',review:'Em revisão',personal_device:'Celular',shared_terminal:'Terminal compartilhado',admin_demo:'Ajuste administrativo'})[v]||String(v||'—');const stat=(k,v)=>`<article class="card stat"><small>${esc(k)}</small><strong>${esc(v)}</strong></article>`;
let faceApiReady=null;async function loadFaceApi(){if(faceApiReady)return faceApiReady;faceApiReady=new Promise((resolve,reject)=>{if(window.faceapi)return resolve(window.faceapi);const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.js';script.onload=()=>resolve(window.faceapi);script.onerror=()=>reject(Error('Não foi possível carregar o reconhecimento facial')) ;document.head.append(script)}).then(async f=>{const base='https://cdn.jsdelivr.net/gh/vladmandic/face-api/model';await Promise.all([f.nets.ssdMobilenetv1.loadFromUri(base),f.nets.faceLandmark68Net.loadFromUri(base),f.nets.faceRecognitionNet.loadFromUri(base)]);return f});faceApiReady.catch(()=>{faceApiReady=null});return faceApiReady}
async function faceDescriptor(video){const f=await loadFaceApi();const r=await f.detectSingleFace(video,new f.SsdMobilenetv1Options({minConfidence:0.65})).withFaceLandmarks().withFaceDescriptor();if(!r)throw Error('Não detectei um rosto. Olhe para a câmera com boa iluminação.');return Array.from(r.descriptor)}
async function withCamera(run){if(!navigator.mediaDevices?.getUserMedia)throw Error('Este aparelho/navegador não liberou acesso à câmera');const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;const dialog=document.createElement('dialog');dialog.className='dialog';dialog.innerHTML='<form class="card dialog-card" method="dialog"><h2>Reconhecimento facial</h2><p>O vetor facial será comparado ao cadastro. Foto e vídeo não serão enviados ou armazenados. A câmera deve estar liberada pelo aparelho.</p><div id="face-camera"></div><div class="actions"><button class="secondary" value="cancel">Cancelar</button><button class="primary" id="face-capture" type="button">Capturar</button></div></form>';dialog.querySelector('#face-camera').append(video);document.body.append(dialog);let stream;try{dialog.showModal();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});video.srcObject=stream;await new Promise((resolve,reject)=>{video.onloadedmetadata=resolve;video.onerror=()=>reject(Error('Câmera indisponível'))});return await new Promise((resolve,reject)=>{dialog.addEventListener('cancel',()=>reject(Error('Captura cancelada')),{once:true});dialog.querySelector('#face-capture').onclick=async()=>{const b=dialog.querySelector('#face-capture');b.disabled=true;try{resolve(await run(video))}catch(e){reject(e)}finally{b.disabled=false}}})}finally{stream?.getTracks().forEach(t=>t.stop());dialog.close();dialog.remove()}}
async function faceStatus(){return api('/api/employee/face-profile')}
async function enrollFace(){try{if(!confirm('Consentimento separado: autoriza armazenar o modelo facial (não a foto) para conferir suas marcações? O reconhecimento NÃO prova vida real e pode ser enganado por foto ou tela.'))return;const descriptor=await withCamera(faceDescriptor);await api('/api/employee/face-profile',{method:'PUT',body:JSON.stringify({consent:true,descriptor})});message('Cadastro facial realizado. Nenhuma foto foi armazenada.')}catch(e){message(e.message,true)}await load('worker')}
async function withdrawFace(){if(!confirm('Apagar o modelo facial e retirar seu consentimento?'))return;try{await api('/api/employee/face-profile',{method:'DELETE'});message('Modelo apagado e consentimento retirado.')}catch(e){message(e.message,true)}await load('worker')}
async function render(v){if(v==='dashboard'){if(user.role==='employee')return await render('worker');if(!['company_admin','manager','hr','supervisor'].includes(user.role))throw Error('Seu perfil ainda não tem acesso ao painel de gestão.');const [e,b,s,r,a]=await Promise.all(['/api/employees','/api/branches','/api/schedules','/api/clock-events','/api/adjustment-requests'].map(api));cache={...cache,employees:e.items,branches:b.items,schedules:s.items,records:r.items,requests:a.items};const pending=a.items.filter(x=>x.status==='pending').length;const latest=r.items.slice(0,5);const eventNames={entry:'Entrada',break_start:'Saída para intervalo',break_end:'Retorno do intervalo',exit:'Saída'};return `<div class="dashboard-intro"><div><p class="eyebrow">DADOS REAIS · EMPRESA AUTENTICADA</p><h2>${esc(user.company.name)}</h2><p>Resumo atualizado com os dados disponíveis na API para esta empresa.</p></div><span class="status status-ok">Conectado · sessão autenticada</span></div><div class="grid stats">${stat('Funcionários',e.items.length)}${stat('Filiais',b.items.length)}${stat('Jornadas',s.items.length)}${stat('Marcações',r.items.length)}${stat('Ajustes pendentes',pending)}</div><div class="dashboard-grid"><article class="card"><div class="toolbar"><div><h2>Marcações recentes</h2><p>Últimos registros recebidos pela organização</p></div><button class="secondary" data-view="records">Ver registros</button></div>${latest.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Marcações recentes"><table><thead><tr><th>Funcionário</th><th>Tipo</th><th>Data e hora</th><th>Estado</th></tr></thead><tbody>${latest.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(eventNames[x.event_type]||x.event_type)}</td><td>${esc(formatDateTime(x.occurred_at))}</td><td>${esc(statusLabel(x.validation_status))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><strong>Nenhuma marcação registrada</strong><p>Quando um funcionário marcar o ponto, o registro aparecerá aqui.</p></div>'}</article><article class="card"><div class="toolbar"><div><h2>Solicitações de ajuste</h2><p>Fila real da organização</p></div><button class="secondary" data-view="requests">Ver solicitações</button></div><div class="grid stats compact-stats">${stat('Pendentes',pending)}${stat('Em análise',a.items.filter(x=>x.status==='needs_info').length)}</div>${a.items.length?`<ul class="activity-list">${a.items.slice(0,5).map(x=>`<li><span><b>${esc(x.full_name)}</b><small>${esc(eventNames[x.requested_type]||x.requested_type)} · ${esc(formatDateTime(x.requested_at))}</small></span><span class="status ${x.status==='pending'?'status-warn':'status-neutral'}">${esc(x.status)}</span></li>`).join('')}</ul>`:'<div class="empty-state">Nenhuma solicitação de ajuste.</div>'}</article></div><article class="card"><div class="toolbar"><div><h2>Estrutura da empresa</h2><p>Cadastros reais vinculados à empresa autenticada.</p></div></div><div class="grid stats compact-stats">${stat('Funcionários ativos',e.items.filter(x=>x.status==='active').length)}${stat('Filiais ativas',b.items.filter(x=>x.status==='active').length)}${stat('Jornadas ativas',s.items.filter(x=>x.status==='active').length)}</div></article>`}

if(v==='employees'&&!['company_admin','manager','hr','supervisor'].includes(user.role)){throw Error('Você não tem permissão para consultar a equipe.')}if(v==='employees'){const [d,b,dp,sc]=await Promise.all([api('/api/employees'),api('/api/branches'),api('/api/departments'),api('/api/schedules')]);cache.branches=b.items;cache.departments=dp.items;cache.schedules=sc.items;cache.employees=d.items;const rows=d.items.filter(x=>`${x.employee_number||''} ${x.full_name||''} ${x.job_title||''} ${x.branch_name||''} ${x.department_name||''}`.toLowerCase().includes(employeeQuery.toLowerCase()));return `<div class="toolbar"><div><h2>Funcionários</h2><p>Lista real da sua organização · ${d.items.length} cadastros</p></div>${['company_admin','hr'].includes(user.role)?'<button class="primary" id="new-employee">Novo cadastro</button>':''}</div><div class="filter-row"><input id="employee-search" class="search-control" type="search" placeholder="Buscar nome, matrícula, cargo ou filial" value="${esc(employeeQuery)}" aria-label="Buscar funcionários"><span class="muted">${rows.length} resultado(s) de ${d.items.length}</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabela de funcionários; deslize horizontalmente para ver todas as colunas"><table><thead><tr><th>Matrícula</th><th>Nome</th><th>Cargo</th><th>Filial</th><th>Departamento</th><th>Jornada</th><th>Status</th><th>Acesso ao portal</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.employee_number||'—')}</td><td>${esc(x.full_name)}</td><td>${esc(x.job_title||'—')}</td><td>${esc(x.branch_name||'—')}</td><td>${esc(x.department_name||'—')}</td><td>${esc(x.schedule_name||'—')}</td><td>${esc(statusLabel(x.status))}</td><td>${x.has_portal_access?'Ativo':'Sem acesso'}</td><td>${['company_admin','hr'].includes(user.role)?`<button class="small" data-edit="${esc(x.id)}" aria-label="Editar ${esc(x.full_name)}">Editar</button> ${!x.has_portal_access?`<button class="small" data-account="${esc(x.id)}">Criar acesso</button>`:''}`:'—'}</td></tr>`).join('')||'<tr><td colspan="9">Nenhum funcionário cadastrado nesta organização.</td></tr>'}</tbody></table></div>`}
if(v==='branches'&&!['company_admin','manager','hr','supervisor'].includes(user.role)){throw Error('Você não tem permissão para consultar filiais.')}if(v==='branches'){const [d,dp]=await Promise.all([api('/api/branches'),api('/api/departments')]);cache.branches=d.items;cache.departments=dp.items;return `<div class="toolbar"><div><h2>Filiais</h2><p>Unidades cadastradas nesta organização.</p></div>${['company_admin','hr'].includes(user.role)?'<button class="primary" id="new-branch">Nova filial</button>':''}</div>${d.items.length?`<div class="grid">${d.items.map(x=>`<article class="card"><div class="toolbar"><h2>${esc(x.name)}</h2>${['company_admin','hr'].includes(user.role)?`<button class="small" data-edit-branch="${esc(x.id)}">Editar</button>`:''}</div><p>${esc(x.address||'Endereço não informado')}</p><p>Status: ${esc(x.status)}</p></article>`).join('')}</div>`:'<div class="card">Nenhuma filial cadastrada nesta organização.</div>'}<div class="toolbar"><h2>Departamentos</h2>${['company_admin','hr'].includes(user.role)?'<button class="primary" id="new-department">Novo departamento</button>':''}</div>${dp.items.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Departamento</th><th>Filial</th><th></th></tr></thead><tbody>${dp.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.branch_name||'Todas')}</td><td>${['company_admin','hr'].includes(user.role)?`<button class="small" data-edit-department="${esc(x.id)}">Editar</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card">Nenhum departamento cadastrado nesta organização.</div>'}`}
if(v==='schedules'&&!['company_admin','manager','hr','supervisor'].includes(user.role)){throw Error('Você não tem permissão para consultar jornadas.')}if(v==='schedules'){const d=await api('/api/schedules');cache.schedules=d.items;return `<div class="toolbar"><div><h2>Jornadas</h2><p>Modelos salvos no banco. Não calculam folha ou conformidade legal.</p></div>${['company_admin','hr'].includes(user.role)?'<button class="primary" id="new-schedule">Nova jornada</button>':''}</div>${d.items.length?`<div class="grid">${d.items.map(x=>`<article class="card"><div class="toolbar"><h2>${esc(x.name)}</h2>${['company_admin','hr'].includes(user.role)?`<button class="small" data-edit-schedule="${esc(x.id)}">Editar</button>`:''}</div><pre>${esc(JSON.stringify(x.rules,null,2))}</pre><p>${esc(x.status)} · versão ${esc(x.version)}</p></article>`).join('')}</div>`:'<div class="card">Nenhuma jornada cadastrada nesta organização.</div>'}`}
if(v==='records'){const d=await api('/api/clock-events');const eventNames={entry:'Entrada',break_start:'Saída para intervalo',break_end:'Retorno do intervalo',exit:'Saída'};const rows=d.items.filter(x=>`${x.full_name} ${x.event_type} ${x.source} ${x.validation_status}`.toLowerCase().includes(recordQuery.toLowerCase())&&(recordTypeFilter==='Todos'||x.event_type===recordTypeFilter));return `<article class="card"><h2>Registros de ponto</h2><p>Marcações persistidas da empresa autenticada; o horário é fornecido pelo servidor.</p></article><div class="filter-row"><input id="records-search" class="search-control" type="search" placeholder="Buscar funcionário, tipo ou estado" value="${esc(recordQuery)}" aria-label="Buscar marcações"><select id="records-type" class="select-control" aria-label="Filtrar por tipo de marcação"><option>Todos</option><option value="entry" ${recordTypeFilter==='entry'?'selected':''}>Entrada</option><option value="break_start" ${recordTypeFilter==='break_start'?'selected':''}>Saída para intervalo</option><option value="break_end" ${recordTypeFilter==='break_end'?'selected':''}>Retorno do intervalo</option><option value="exit" ${recordTypeFilter==='exit'?'selected':''}>Saída</option></select><span class="muted">${rows.length} de ${d.items.length} registros</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Funcionário</th><th>Tipo</th><th>Data/hora</th><th>Origem</th><th>Dispositivo</th><th>Validação</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(eventNames[x.event_type]||x.event_type)}</td><td>${esc(formatDateTime(x.occurred_at))}</td><td>${esc(statusLabel(x.source))}</td><td>${esc(x.device_id||'—')}</td><td>${esc(statusLabel(x.validation_status))}</td></tr>`).join('')||'<tr><td colspan="6">Nenhuma marcação registrada no período disponível.</td></tr>'}</tbody></table></div>`}
if(v==='requests'&&!['company_admin','manager','hr','supervisor','employee'].includes(user.role)){throw Error('Você não tem permissão para consultar ajustes.')}if(v==='requests'){const d=await api('/api/adjustment-requests');cache.requests=d.items;const rows=d.items.filter(x=>`${x.full_name} ${x.requested_type} ${x.reason} ${x.status}`.toLowerCase().includes(requestQuery.toLowerCase())&&(requestStatusFilter==='Todos'||x.status===requestStatusFilter));const canReview=['company_admin','manager','hr','supervisor'].includes(user.role);return `<article class="card"><h2>Solicitações de ajuste</h2><p>Decisões são registradas em trilha de auditoria; a marcação original é preservada.</p></article><div class="filter-row"><input id="requests-search" class="search-control" type="search" placeholder="Buscar funcionário, justificativa ou tipo" value="${esc(requestQuery)}" aria-label="Buscar solicitações"><select id="requests-status" class="select-control" aria-label="Filtrar solicitações por estado"><option>Todos</option><option value="pending" ${requestStatusFilter==='pending'?'selected':''}>Pendente</option><option value="approved" ${requestStatusFilter==='approved'?'selected':''}>Aprovado</option><option value="rejected" ${requestStatusFilter==='rejected'?'selected':''}>Rejeitado</option><option value="needs_info" ${requestStatusFilter==='needs_info'?'selected':''}>Precisa de informação</option></select><span class="muted">${rows.length} de ${d.items.length} solicitações</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabela de solicitações; deslize horizontalmente para ver todas as colunas"><table><thead><tr><th>Funcionário</th><th>Tipo</th><th>Data pedida</th><th>Justificativa</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(eventLabel(x.requested_type))}</td><td>${esc(formatDateTime(x.requested_at))}</td><td>${esc(x.reason)}</td><td>${esc(statusLabel(x.status))}</td><td>${canReview&&x.status==='pending'?`<button class="small" data-review="${esc(x.id)}">Revisar</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6">Nenhuma solicitação de ajuste encontrada.</td></tr>'}</tbody></table></div>`}
if(v==='users'&&!['company_admin','hr'].includes(user.role)){throw Error('Seu perfil não pode consultar contas da organização.')}if(v==='users'&&!['company_admin','hr'].includes(user.role))throw Error('Seu perfil não pode consultar contas da organização.');if(v==='users'){const [d,e]=await Promise.all([api('/api/accounts'),api('/api/employees')]);cache.accounts=d.items;cache.employees=e.items;return `<div class="toolbar"><div><h2>Contas e acessos</h2><p>Contas individuais vinculadas à organização.</p></div>${user.role==='company_admin'?'<button class="primary" id="new-account">Criar acesso</button>':''}</div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Funcionário</th><th>Identificador</th><th>Estado</th><th>Senha atualizada</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.display_name)}</td><td>${esc(x.email)}</td><td>${esc(x.role)}</td><td>${esc(x.employee_name||'—')}</td><td>${esc(x.id)}</td><td>${esc(statusLabel(x.status))}</td><td>${esc(x.password_changed_at||'—')}</td><td>${user.role==='company_admin'?(x.id!==user.id||x.status==='disabled'?x.status==='active'?`<button class="small" data-disable-account="${esc(x.id)}">Desativar</button>`:`<button class="small" data-enable-account="${esc(x.id)}">Reativar</button>`:'—')+(x.status==='active'?` <button class="small" data-reset-password="${esc(x.id)}">Redefinir senha</button>`:''):'—'}</td></tr>`).join('')||'<tr><td colspan="8">Nenhuma conta.</td></tr>'}</tbody></table></div>`}
if(v==='worker'&&(user.role!=='employee'||!user.employee_id)){throw Error('Acesso ao portal do funcionário não está vinculado a este perfil.')}if(v==='worker'){const [r,a]=await Promise.all([api('/api/clock-events'),api('/api/adjustment-requests')]);cache.worker={records:r.items,requests:a.items};return `<article class="card"><h2>Olá, ${esc(user.name)}</h2><p>Registre sua jornada após conferência facial. O horário é fornecido pelo servidor da organização.</p><div id="face-status" class="message">Verificando cadastro facial…</div><div class="actions"><button class="secondary" id="enroll-face">Cadastrar rosto</button><button class="secondary" id="withdraw-face">Apagar rosto / retirar consentimento</button><button class="primary" data-clock="entry">Registrar entrada</button><button class="secondary" data-clock="break_start">Iniciar intervalo</button><button class="secondary" data-clock="break_end">Voltar do intervalo</button><button class="primary" data-clock="exit">Registrar saída</button></div><button class="secondary" id="new-adjustment">Solicitar ajuste</button></article><div class="toolbar"><h2>Meus registros</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Data/hora</th><th>Tipo</th><th>Origem</th><th>Status</th></tr></thead><tbody>${r.items.map(x=>`<tr><td>${esc(formatDateTime(x.occurred_at))}</td><td>${esc(eventLabel(x.event_type))}</td><td>${esc(statusLabel(x.source))}</td><td>${esc(statusLabel(x.validation_status))}</td></tr>`).join('')||'<tr><td colspan="4">Nenhum registro disponível.</td></tr>'}</tbody></table></div><h2>Minhas solicitações</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Data solicitada</th><th>Tipo</th><th>Justificativa</th><th>Status</th></tr></thead><tbody>${a.items.map(x=>`<tr><td>${esc(formatDateTime(x.requested_at))}</td><td>${esc(eventLabel(x.requested_type))}</td><td>${esc(x.reason)}</td><td>${esc(statusLabel(x.status))}</td></tr>`).join('')||'<tr><td colspan="4">Nenhuma solicitação de ajuste encontrada.</td></tr>'}</tbody></table></div>`}
if(v==='password'){return `<article class="card"><h2>Alterar minha senha</h2><p>Use uma senha exclusiva, com pelo menos 14 caracteres.</p><form id="password-form"><label>Senha atual<input name="current_password" type="password" autocomplete="current-password" required></label><label>Nova senha<input name="new_password" type="password" minlength="14" autocomplete="new-password" required></label><button class="primary">Atualizar senha</button></form><div id="password-msg" class="message" hidden></div></article>`}
if(v==='terminals'&&!['company_admin','hr'].includes(user.role))throw Error('Somente o administrador titular e o RH gerenciam dispositivos.');if(v==='terminals'){const [d,b]=await Promise.all([api('/api/devices'),api('/api/branches')]);cache.devices=d.items;cache.branches=b.items;return `<div class="toolbar"><div><h2>Dispositivos autorizados</h2><p>Credenciais individuais por dispositivo; revogação imediata. A captura oficial ainda permanece bloqueada pelo servidor.</p></div>${user.role==='company_admin'||user.role==='hr'?'<button class="primary" id="new-device">Autorizar dispositivo</button>':''}</div>${d.items.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Dispositivo</th><th>Filial</th><th>Status</th><th>Último uso</th><th>Ação</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.label)}</td><td>${esc(x.branch_name||'—')}</td><td>${esc(statusLabel(x.status))}</td><td>${esc(formatDateTime(x.last_seen_at))}</td><td>${x.status==='active'?`<button class="small" data-revoke-device="${esc(x.id)}" aria-label="Revogar ${esc(x.label)}">Revogar</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<article class="card">Nenhum dispositivo autorizado.</article>'}<article class="card"><b>Importante:</b> a autorização técnica não libera marcações oficiais. A liberação exige conferência do acordo coletivo REP-A, AFD e assinatura ICP-Brasil, identificação do estabelecimento, comprovante assinado e aprovação de privacidade.</article>`}
if(v==='settings'){if(!['company_admin','hr'].includes(user.role))throw Error('Configurações restritas ao administrador titular e RH.');const [profile,agreements]=await Promise.all([api('/api/company/rep-a-profile'),api('/api/rep-a/authorization')]);cache.repAProfile=profile.items;cache.repAAgreements=agreements.items;const c=profile.items[0]||{};return `<article class="card"><h2>Perfil do empregador (REP-A)</h2><p>Esses dados alimentam a identificação do empregador/estabelecimento; preencha de fonte oficial.</p><form id="rep-a-company-form"><label>Tipo do identificador<select name="employer_id_type"><option value="cnpj" ${c.employer_id_type==='cnpj'?'selected':''}>CNPJ</option><option value="cpf" ${c.employer_id_type==='cpf'?'selected':''}>CPF</option></select></label><label>CNPJ/CPF (somente números)<input name="employer_id" inputmode="numeric" value="${esc(c.employer_id||'')}"></label><label>Razão social/nome oficial<input name="employer_legal_name" maxlength="200" value="${esc(c.employer_legal_name||'')}"></label><label>CAEPF/CNO (se houver)<input name="employer_caepf_cno" value="${esc(c.employer_caepf_cno||'')}"></label><label>Contato de privacidade da organização<input name="privacy_contact" maxlength="200" value="${esc(c.privacy_contact||'')}"></label><button class="primary">Salvar dados do empregador</button></form><div id="rep-a-company-msg" class="message" hidden></div></article><article class="card"><h2>Autorização coletiva REP-A</h2><p>O uso só é válido enquanto vigorar convenção/acordo coletivo. O Certus não consegue verificar automaticamente autenticidade, categoria ou abrangência.</p><form id="rep-a-agreement-form"><label>Instrumento<select name="instrument_type"><option value="collective_agreement">Acordo coletivo</option><option value="collective_convention">Convenção coletiva</option><option value="addendum">Termo aditivo</option></select></label><label>Número do processo depositado no Mediador (17 dígitos)<input name="deposited_process_number" inputmode="numeric" pattern="[0-9]{17}" maxlength="17" required></label><label>Válido desde<input name="valid_from" type="date" required></label><label>Válido até<input name="valid_until" type="date" required></label><label>Referência do documento/URL oficial e cláusula autorizadora<textarea name="document_reference" minlength="5" maxlength="500" required></textarea></label><button class="primary">Cadastrar para conferência</button></form><div id="rep-a-agreement-msg" class="message" hidden></div><p class="muted">O cadastro fica pendente. O administrador titular pode atestar que conferiu documento, partes/abrangência, cláusula REP-A e vigência atual; isso será auditado, não validado automaticamente pelo Certus.</p>${agreements.items.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Tabela; deslize horizontalmente para consultar todas as colunas"><table><thead><tr><th>Instrumento</th><th>Processo</th><th>Vigência</th><th>Status</th><th>Referência</th><th>Ação</th></tr></thead><tbody>${agreements.items.map(a=>`<tr><td>${esc(a.instrument_type)}</td><td>${esc(a.deposited_process_number)}</td><td>${esc(a.valid_from)} a ${esc(a.valid_until)}</td><td>${esc(a.status)}</td><td>${esc(a.document_reference)}</td><td>${a.status==='pending'?`<button class="small" data-validate-repa="${esc(a.id)}">Atestar</button>`:a.status==='validated'?`<button class="small" data-revoke-repa="${esc(a.id)}">Revogar</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:''}</article><article class="card"><h2>Estado de conformidade e privacidade</h2><p><b>Captura oficial:</b> bloqueada até implementação/verificação do AFD REP-A, CPF do trabalhador e estabelecimento, assinatura ICP-Brasil e revisão do instrumento coletivo vigente.</p><p><b>Biometria facial:</b> cadastro e retirada de consentimento ficam disponíveis no portal do funcionário; o sistema não tem prova de vida.</p><p>O REP-A depende de acordo/convenção coletivo vigente; devem ser atendidos os controles de extração para fiscalização. Relatórios Espelho/AEJ podem depender da data do instrumento. Nenhum cálculo legal está implementado.</p><p>Defina com a organização finalidade e base legal, transparência, retenção e descarte, atendimento a titulares e resposta a incidentes. Fonte: <a href="https://www.gov.br/trabalho-e-emprego/pt-br/assuntos/inspecao-do-trabalho/fiscalizacao-do-trabalho/Perguntas%20e%20Respostas%20REP" target="_blank" rel="noopener">MTE — perguntas e respostas</a>.</p></article>`} 
if(v==='reports'&&!['company_admin','manager','hr','supervisor'].includes(user.role))throw Error('Seu perfil não pode exportar relatórios.');if(v==='reports'){const [e,r]=await Promise.all([api('/api/employees'),api('/api/clock-events')]);return `<div class="toolbar"><div><h2>Exportação de dados</h2><p>Exporta os dados persistidos disponíveis à sua sessão. O arquivo contém registros brutos: não calcula folha, horas extras ou banco de horas.</p></div><button class="primary" id="export-report" aria-label="Baixar exportação CSV de funcionários e marcações">Baixar CSV</button></div><div class="grid stats">${stat('Funcionários',e.items.length)}${stat('Marcações',r.items.length)}</div><article class="card"><h2>Escopo e limitações</h2><p>O CSV contém dados brutos da API; não calcula jornada, folha, horas extras, faltas, tolerâncias, feriados ou convenção coletiva. Confira tudo antes de qualquer uso.</p></article><article class="card export-status"><h2>Exportações oficiais AFD / AEJ</h2><p>Os endpoints existem, mas no momento estão bloqueados pela configuração de identidade do desenvolvedor. AFD retornou 503 por ausência de CERTUS_DEVELOPER_ID; AEJ também exige nome, razão social e e-mail do desenvolvedor. Além disso, cada filial, funcionário e período precisam dos identificadores e metadados oficiais completos. Não gerar arquivos incompletos.</p><span class="status status-warn">Indisponível até configuração e validação</span></article><div id="report-data" hidden data-employees="${esc(JSON.stringify(e.items))}" data-records="${esc(JSON.stringify(r.items))}"></div>`}
return '<article class="card"><h2>Não disponível para operação</h2><p>Terminais, biometria/liveness, relatórios legais, gestão de usuários e convites, recuperação de senha, jornadas completas e configurações avançadas ainda precisam ser implementados e validados. Não estão sendo apresentados como funcionais.</p></article>'}
async function recordClock(type){const labels={entry:'entrada',break_start:'início do intervalo',break_end:'retorno do intervalo',exit:'saída'};if(!labels[type])return;const button=$(`[data-clock="${type}"]`);if(button)button.disabled=true;try{const descriptor=await withCamera(faceDescriptor);await api('/api/clock-events',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({event_type:type,face_descriptor:descriptor})});message(`Reconhecimento facial conferido e marcação de ${labels[type]} registrada.`);await load('worker')}catch(e){message(e.message,true)}finally{const current=$(`[data-clock="${type}"]`);if(current)current.disabled=false}}
function bind(){const filterInput=(selector,setter)=>{const el=$(selector);if(el)el.addEventListener('input',()=>{setter(el.value);const pos=el.selectionStart;clearTimeout(el._filterTimer);el._filterTimer=setTimeout(async()=>{await load(view);const next=$(selector);if(next){next.focus();try{next.setSelectionRange(pos,pos)}catch{}}},160)})};filterInput('#employee-search',v=>employeeQuery=v);filterInput('#records-search',v=>recordQuery=v);filterInput('#requests-search',v=>requestQuery=v);$('#records-type')?.addEventListener('change',e=>{recordTypeFilter=e.target.value;load(view)});$('#requests-status')?.addEventListener('change',e=>{requestStatusFilter=e.target.value;load(view)});$('#enroll-face')?.addEventListener('click',enrollFace);$('#withdraw-face')?.addEventListener('click',withdrawFace);if($('#face-status'))faceStatus().then(x=>$('#face-status').textContent=x.registered?'Rosto cadastrado.':'Cadastre seu rosto antes de marcar.').catch(()=>$('#face-status').textContent='Não foi possível consultar o cadastro facial.');$$('[data-clock]').forEach(b=>b.onclick=()=>recordClock(b.dataset.clock));$('#new-employee')?.addEventListener('click',()=>employeeForm());$$('[data-edit]').forEach(b=>b.onclick=()=>employeeForm(cache.employees.find(x=>x.id===b.dataset.edit)));$('#new-branch')?.addEventListener('click',branchForm);$('#new-schedule')?.addEventListener('click',scheduleForm);$('#new-department')?.addEventListener('click',departmentForm);$$('[data-edit-branch]').forEach(b=>b.onclick=()=>branchForm(cache.branches.find(x=>x.id===b.dataset.editBranch)));$$('[data-edit-department]').forEach(b=>b.onclick=()=>departmentForm(cache.departments.find(x=>x.id===b.dataset.editDepartment)));$$('[data-edit-schedule]').forEach(b=>b.onclick=()=>scheduleForm(cache.schedules.find(x=>x.id===b.dataset.editSchedule)));$$('[data-account]').forEach(b=>b.onclick=()=>employeeAccountForm(b.dataset.account));$('#rep-a-company-form')?.addEventListener('submit',saveRepACompany);$('#rep-a-agreement-form')?.addEventListener('submit',saveRepAAgreement);$$('[data-validate-repa]').forEach(b=>b.onclick=()=>attestRepAAgreement(b.dataset.validateRepa));$$('[data-revoke-repa]').forEach(b=>b.onclick=()=>revokeRepAAgreement(b.dataset.revokeRepa));$('#export-report')?.addEventListener('click',exportReport);$('#new-adjustment')?.addEventListener('click',adjustmentForm);$('#new-account')?.addEventListener('click',accountForm);$('#new-device')?.addEventListener('click',deviceForm);$$('[data-revoke-device]').forEach(b=>b.onclick=()=>revokeDevice(b.dataset.revokeDevice));$$('[data-disable-account]').forEach(b=>b.onclick=()=>changeAccountStatus(b.dataset.disableAccount,'disabled'));$$('[data-enable-account]').forEach(b=>b.onclick=()=>changeAccountStatus(b.dataset.enableAccount,'active'));$$('[data-reset-password]').forEach(b=>b.onclick=()=>resetAccountPassword(b.dataset.resetPassword));$('#password-form')?.addEventListener('submit',changePassword);$$('[data-review]')?.forEach(b=>b.onclick=()=>reviewForm(b.dataset.review));$$('[data-account]')?.forEach(b=>b.onclick=()=>employeeAccountForm(b.dataset.account))}
function openModal(title,fields,save){const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<form class="card dialog-card" method="dialog"><button class="x" value="cancel">×</button><h2>${title}</h2>${fields}<div id="modal-msg" class="message" hidden></div><div class="actions"><button class="secondary" value="cancel">Cancelar</button><button class="primary" type="button" id="save">Salvar</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('#save').onclick=async()=>{const b=d.querySelector('#save');b.disabled=true;try{await save(d);d.close();await load(view)}catch(e){const m=d.querySelector('#modal-msg');m.hidden=false;m.textContent=e.message;b.disabled=false}};d.addEventListener('close',()=>d.remove())}
async function showDeviceSecret(label,secret){const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<form class="card dialog-card" method="dialog"><h2>Chave do dispositivo</h2><p>${esc(label)}. Copie agora e armazene em cofre seguro. A chave não poderá ser consultada novamente.</p><label>Chave secreta<input readonly id="device-secret-once" value="${esc(secret)}"></label><div class="actions"><button class="secondary" id="copy-device-secret" type="button">Copiar chave</button><button class="primary" value="done">Concluir</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('#copy-device-secret').onclick=async()=>{try{await navigator.clipboard.writeText(secret);d.querySelector('#copy-device-secret').textContent='Copiada'}catch{d.querySelector('#device-secret-once').select()}};d.addEventListener('close',()=>{d.remove();load(view)})}
function deviceForm(){if(!['company_admin','hr'].includes(user.role)){message('Sem permissão para autorizar dispositivo.',true);return}const opts=(cache.branches||[]).filter(x=>x.status==='active').map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');openModal('Autorizar dispositivo',`<label>Identificação<input name="label" required maxlength="120"></label><label>Filial<select name="branch_id" required>${opts}</select></label><p class="muted">A chave será mostrada uma única vez. Guarde-a num cofre seguro. A autorização não ativa a marcação oficial.</p>`,async d=>{const r=await api('/api/devices',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(d.querySelector('form')).entries()))});d.close();await showDeviceSecret(`Dispositivo ${r.item.label}`,r.device_secret)})}
async function revokeDevice(id){if(!confirm('Revogar este dispositivo agora? Ele deixará de poder autenticar marcações.'))return;try{await api(`/api/devices/${encodeURIComponent(id)}/revoke`,{method:'PATCH',body:JSON.stringify({})});await load(view)}catch(e){message(e.message,true)}}
function employeeForm(x={}){const edit=!!x.id;openModal(edit?'Editar funcionário':'Novo funcionário',`<label>Nome<input name="full_name" required maxlength="160" value="${esc(x.full_name||'')}"></label><label>Matrícula<input name="employee_number" maxlength="80" value="${esc(x.employee_number||'')}"></label><label>Cargo<input name="job_title" maxlength="120" value="${esc(x.job_title||'')}"></label>${!edit?`<label>Filial<select name="branch_id"><option value="">Sem filial</option>${(cache.branches||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label><label>Departamento<select name="department_id"><option value="">Sem departamento</option>${(cache.departments||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label><label>Jornada<select name="schedule_id"><option value="">Sem jornada</option>${(cache.schedules||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></label>`:''}${edit?`<label>CPF do empregado (necessário para AFD)<input name="cpf" inputmode="numeric" maxlength="14" value="${esc(x.cpf||'')}"></label><label>Status<select name="status"><option value="active" ${x.status==='active'?'selected':''}>Ativo</option><option value="inactive" ${x.status==='inactive'?'selected':''}>Inativo</option><option value="leave" ${x.status==='leave'?'selected':''}>Afastado</option></select></label>`:''}<p class="muted">O CPF será limitado ao uso de identificação trabalhista; registre-o somente se autorizado.</p>`,async d=>{const body=Object.fromEntries(new FormData(d.querySelector('form')).entries());const cpf=body.cpf;delete body.cpf;if(body.employee_number==='')body.employee_number=null;await api(edit?`/api/employees/${encodeURIComponent(x.id)}`:'/api/employees',{method:edit?'PATCH':'POST',body:JSON.stringify(body)});if(edit&&cpf)await api(`/api/employees/${encodeURIComponent(x.id)}/rep-a-profile`,{method:'PATCH',body:JSON.stringify({cpf})})})}
function branchForm(x={}){const edit=!!x.id;openModal(edit?'Editar filial':'Nova filial',`<label>Nome<input name="name" required maxlength="120" value="${esc(x.name||'')}"></label><label>Endereço<input name="address" maxlength="300" value="${esc(x.address||'')}"></label>${edit?`<label>CNPJ do estabelecimento (14 dígitos)<input name="establishment_id" inputmode="numeric" maxlength="18" value="${esc(x.establishment_id||'')}"></label><label>Local de prestação de serviços<input name="service_location" maxlength="100" value="${esc(x.service_location||'')}"></label><label>Status<select name="status"><option value="active" ${x.status==='active'?'selected':''}>Ativa</option><option value="inactive" ${x.status==='inactive'?'selected':''}>Inativa</option></select></label>`:''}`,async d=>{const body=Object.fromEntries(new FormData(d.querySelector('form')).entries());if(edit){const profile={establishment_id:body.establishment_id,service_location:body.service_location};delete body.establishment_id;delete body.service_location;await api(`/api/branches/${encodeURIComponent(x.id)}/rep-a-profile`,{method:'PATCH',body:JSON.stringify(profile)});await api(`/api/branches/${encodeURIComponent(x.id)}`,{method:'PATCH',body:JSON.stringify(body)})}else await api('/api/branches',{method:'POST',body:JSON.stringify(body)})})}
function scheduleForm(x={}){const edit=!!x.id;openModal(edit?'Editar jornada':'Nova jornada',`<label>Nome<input name="name" required maxlength="120" value="${esc(x.name||'')}"></label><label>Regras JSON<textarea name="rules" rows="6" required>${esc(JSON.stringify(x.rules||{dias:['seg','ter','qua','qui','sex'],entrada:'08:00',saida:'17:00'},null,2))}</textarea></label>${edit?`<label>Status<select name="status"><option value="active" ${x.status==='active'?'selected':''}>Ativa</option><option value="inactive" ${x.status==='inactive'?'selected':''}>Inativa</option></select></label>`:''}<p class="muted">As regras salvas ainda não calculam folha.</p>`,async d=>{const f=new FormData(d.querySelector('form'));let rules;try{rules=JSON.parse(f.get('rules'));if(!rules||Array.isArray(rules)||typeof rules!=='object')throw 0}catch{throw Error('JSON de regras inválido.')}const body={name:f.get('name'),rules};if(edit)body.status=f.get('status');return api(edit?`/api/schedules/${encodeURIComponent(x.id)}`:'/api/schedules',{method:edit?'PATCH':'POST',body:JSON.stringify(body)})})}
function adjustmentForm(){const events=(cache.worker?.records||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.event_type)} · ${esc(x.occurred_at)}</option>`).join('');openModal('Solicitar ajuste de ponto',`<label>Tipo<select name="requested_type"><option value="entry">Entrada</option><option value="break_start">Saída para intervalo</option><option value="break_end">Retorno do intervalo</option><option value="exit">Saída</option></select></label><label>Data e hora corretas<input name="requested_at" type="datetime-local" required></label><label>Marcação original (opcional)<select name="original_event_id"><option value="">Sem referência</option>${events}</select></label><label>Justificativa (mínimo 5 caracteres)<textarea name="reason" minlength="5" maxlength="2000" required></textarea></label>`,async d=>{const f=new FormData(d.querySelector('form')),body=Object.fromEntries(f.entries());body.requested_at=new Date(body.requested_at).toISOString();if(!body.original_event_id)delete body.original_event_id;await api('/api/adjustment-requests',{method:'POST',body:JSON.stringify(body)})})}
async function startRecovery(){const email=$('#recovery-email')?.value.trim(),m=$('#recovery-result'),b=$('#recovery-submit');if(!email){$('#recovery-email')?.focus();return}b.disabled=true;m.hidden=false;m.className='message bad';m.textContent='A recuperação automática por e-mail ainda não está configurada. Peça ao administrador titular da empresa para redefinir seu acesso. O administrador pode entregar a senha temporária por canal seguro.';b.disabled=false}
async function attestRepAAgreement(id){const confirmed=confirm('Você é o administrador titular e conferiu o documento oficial, empregador/categoria/abrangência, cláusula autorizadora de REP-A e vigência atual? A declaração ficará auditada.');if(!confirmed)return;try{await api(`/api/rep-a/authorization/${encodeURIComponent(id)}/validate`,{method:'POST',body:JSON.stringify({document_verified:true,covers_employer:true,covers_dates:true,authorizes_rep_a:true})});message('Atestação registrada. A captura ainda permanece bloqueada até completar os demais requisitos técnicos e legais.');await load(view)}catch(e){message(e.message,true)}}
async function revokeRepAAgreement(id){const reason=prompt('Motivo da revogação do instrumento coletivo:');if(!reason||reason.trim().length<5)return;try{await api(`/api/rep-a/authorization/${encodeURIComponent(id)}/revoke`,{method:'POST',body:JSON.stringify({reason})});message('Instrumento revogado; a captura não pode prosseguir com essa autorização.');await load(view)}catch(e){message(e.message,true)}}
async function saveRepACompany(e){e.preventDefault();const m=$('#rep-a-company-msg');try{const body=Object.fromEntries(new FormData(e.currentTarget).entries());await api('/api/company/rep-a-profile',{method:'PATCH',body:JSON.stringify(body)});m.hidden=false;m.className='message';m.textContent='Dados salvos. Confira os identificadores e filiais.';await load(view)}catch(err){m.hidden=false;m.className='message bad';m.textContent=err.message}}
async function saveRepAAgreement(e){e.preventDefault();const m=$('#rep-a-agreement-msg');try{const body=Object.fromEntries(new FormData(e.currentTarget).entries());await api('/api/rep-a/authorization',{method:'POST',body:JSON.stringify(body)});m.hidden=false;m.className='message';m.textContent='Instrumento cadastrado como pendente de conferência. Isso não libera o ponto.';await load(view)}catch(err){m.hidden=false;m.className='message bad';m.textContent=err.message}}
async function changePassword(e){e.preventDefault();const f=new FormData(e.currentTarget),msg=$('#password-msg'),b=e.currentTarget.querySelector('button');b.disabled=true;try{const d=await api(user.role==='employee'?'/api/employee/account/password':'/api/account/password',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});msg.hidden=false;msg.textContent='Senha alterada. Entre novamente com a nova senha.';logout('Senha alterada. Entre com a nova senha.')}catch(err){msg.hidden=false;msg.className='message bad';msg.textContent=err.message;b.disabled=false}}
function accountForm(){if(user.role!=='company_admin'){message('Somente o administrador titular pode criar contas da organização.',true);return}const employees=cache.employees||[];openModal('Criar conta de acesso',`<label>Nome<input name="display_name" required maxlength="160"></label><label>E-mail<input name="email" type="email" required></label><label>Perfil<select name="role"><option value="manager">Gerente</option><option value="hr">RH</option><option value="supervisor">Supervisor</option><option value="employee">Funcionário</option></select></label><label>Vincular funcionário (para perfil Funcionário)<select name="employee_id"><option value="">Não vincular</option>${employees.map(e=>`<option value="${esc(e.id)}">${esc(e.full_name)}</option>`).join('')}</select></label><p class="muted">O sistema gera uma senha temporária aleatória. Ela aparece uma única vez para entrega segura; quem receber deve trocá-la imediatamente.</p>`,async d=>{const f=new FormData(d.querySelector('form')),role=f.get('role'),employee_id=f.get('employee_id')||null;if(role==='employee'&&!employee_id)throw Error('Vincule o cadastro de funcionário para criar perfil de funcionário.');if(role!=='employee'&&employee_id)throw Error('Somente perfil funcionário pode ser vinculado a um funcionário.');const r=await api('/api/accounts',{method:'POST',body:JSON.stringify({display_name:f.get('display_name'),email:f.get('email'),role,employee_id})});const pw=r.user.temporary_password;await showTemporaryPassword(r.user.email,pw)})}
async function showTemporaryPassword(email,password){const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<form class="card dialog-card" method="dialog"><h2>Acesso criado</h2><p>Envie esta senha ao usuário por um canal seguro. Ela não será exibida novamente.</p><label>E-mail<input readonly value="${esc(email)}"></label><label>Senha temporária<input readonly id="temp-pw" value="${esc(password)}"></label><div class="actions"><button class="secondary" type="button" id="copy-temp">Copiar senha</button><button class="primary" value="ok">Concluir</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('#copy-temp').onclick=async()=>{await navigator.clipboard.writeText(password);d.querySelector('#copy-temp').textContent='Copiada'};d.addEventListener('close',()=>{d.remove();load(view)})}
async function resetAccountPassword(id){if(user.role!=='company_admin'){message('Somente o administrador titular pode redefinir senhas.',true);return}if(!confirm('Gerar uma senha temporária nova? A senha atual será invalidada imediatamente.'))return;try{const r=await api(`/api/admin/accounts/${encodeURIComponent(id)}/reset-password`,{method:'POST',body:JSON.stringify({})});await showTemporaryPassword(r.email,r.temporary_password)}catch(e){message(e.message,true)}}
async function changeAccountStatus(id,status){if(user.role!=='company_admin'){message('Somente o administrador titular pode alterar o estado de contas.',true);return}if(!confirm(status==='disabled'?'Desativar este acesso? Todas as sessões existentes serão invalidadas pelo servidor.':'Reativar este acesso?'))return;try{await api(`/api/accounts/${encodeURIComponent(id)}/status`,{method:'PATCH',body:JSON.stringify({status})});if(status==='disabled'){const row=(cache.accounts||[]).find(x=>x.id===id);if(row)row.status='disabled'}await load(view)}catch(e){message(e.message,true)}}
function employeeAccountForm(id){const x=(cache.employees||[]).find(e=>e.id===id);if(!x)return;openModal('Criar acesso individual',`<p>Funcionário: <b>${esc(x.full_name)}</b></p><label>E-mail<input name="email" type="email" required autocomplete="off"></label><label>Senha inicial (mínimo 14 caracteres)<input name="password" type="password" minlength="14" required autocomplete="new-password"></label><p class="muted">Entregue a senha ao funcionário por um canal seguro. A área de acesso individual permitirá que ele altere a senha depois do primeiro login.</p>`,async d=>{const f=new FormData(d.querySelector('form'));await api(`/api/employees/${encodeURIComponent(id)}/account`,{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),display_name:x.full_name})})})}
function departmentForm(x={}){const edit=!!x.id,opts=(cache.branches||[]).map(b=>`<option value="${esc(b.id)}" ${x.branch_id===b.id?'selected':''}>${esc(b.name)}</option>`).join('');openModal(edit?'Editar departamento':'Novo departamento',`<label>Nome<input name="name" required maxlength="120" value="${esc(x.name||'')}"></label><label>Filial<select name="branch_id"><option value="">Todas as filiais</option>${opts}</select></label>`,async d=>{const f=new FormData(d.querySelector('form')),body=Object.fromEntries(f.entries());if(!body.branch_id)body.branch_id=null;await api(edit?`/api/departments/${encodeURIComponent(x.id)}`:'/api/departments',{method:edit?'PATCH':'POST',body:JSON.stringify(body)})})}
function exportReport(){const el=$('#report-data'),employees=JSON.parse(el.dataset.employees||'[]'),records=JSON.parse(el.dataset.records||'[]');const rows=[['tipo','id','nome','referencia','status'],...employees.map(x=>['funcionario',x.id,x.full_name,x.employee_number||'',x.status]),...records.map(x=>['marcacao',x.id,x.full_name,`${x.event_type} ${x.occurred_at}`,x.validation_status])];const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='certus-exportacao.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function reviewForm(id){const x=(cache.requests||[]).find(r=>r.id===id);if(!x)return;openModal('Revisar solicitação',`<p><b>${esc(x.full_name)}</b> · ${esc(x.requested_type)} · ${esc(x.requested_at)}</p><p>${esc(x.reason)}</p><label>Decisão<select name="action"><option value="approved">Aprovar</option><option value="rejected">Rejeitar</option><option value="needs_info">Solicitar informação</option></select></label><label>Nota obrigatória<textarea name="note" required minlength="3" maxlength="2000"></textarea></label><p class="muted">A aprovação grava evento suplementar e preserva o original.</p>`,async d=>{const f=new FormData(d.querySelector('form'));await api(`/api/adjustment-requests/${encodeURIComponent(id)}/decision`,{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))})})}
async function start(){if(!token||!user)return login();try{const d=await api('/api/me');user={...user,...d};sessionStorage.setItem(userKey,JSON.stringify(user));shell()}catch(e){login(e.message)}}
start();
})();